package fit.iuh.foodgobackend.catalog;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import fit.iuh.foodgobackend.common.*;
import fit.iuh.foodgobackend.account.UserPrincipal;
import java.util.*;
class CatalogTests {
 @Test void validatesFilters(){for(var filters:List.of(Map.of("page","-1"),Map.of("size","51"),Map.of("sort","evil"),Map.of("categoryId","0"),Map.of("areaCode","other"),Map.of("page","nan")))assertEquals(400,assertThrows(ApiException.class,()->CatalogQuery.parse(filters)).status);}
 @Test void literalSearchAndBoundedPage(){var q=CatalogQuery.parse(Map.of("q","50%_=","size","2","page","3"));assertEquals("%50=%=_==%",q.like());assertEquals(6,q.offset());var page=q.envelope(List.of(1,2,3));assertEquals(List.of(1,2),page.get("data"));assertEquals(true,((Map<?,?>)page.get("meta")).get("hasNext"));}
 @Test void searchIsBoundAndPaginationHappensInSql(){var db=mock(JpaSql.class);when(db.rows(anyString(),any(Object[].class))).thenReturn(List.of());var service=new CatalogService(db);service.searchFoods(Map.of("q","' OR 1=1 --","categoryId","2","restaurantId","3","sort","price","page","1","size","5"));var inv=mockingDetails(db).getInvocations().iterator().next();String sql=inv.getArgument(0);assertFalse(sql.contains("OR 1=1"));assertTrue(sql.contains("LIMIT ? OFFSET ?"));assertTrue(sql.contains("r.available=TRUE"));assertTrue(Arrays.asList(inv.getArguments()).contains(6));assertTrue(Arrays.asList(inv.getArguments()).contains(5L));}
 @Test void favoritePutIsIdempotentAndDeleteScoped(){var db=mock(JpaSql.class);var catalog=new CatalogService(db);var s=new FavoriteService(db,catalog);var u=new UserPrincipal(7,"test","CUSTOMER",null,"test");when(db.one("SELECT id FROM favorites WHERE customer_id=? AND food_id=?",7L,12L)).thenReturn(Map.of("id",5));s.save(u,"FOOD",12,true);verify(db,never()).insert(anyString(),anyMap());s.save(u,"FOOD",12,false);s.save(u,"FOOD",12,false);verify(db,times(2)).update("DELETE FROM favorites WHERE customer_id=? AND food_id=?",7L,12L);}
 @Test void favoriteRejectsRoleAndType(){var db=mock(JpaSql.class);var s=new FavoriteService(db,new CatalogService(db));var c=new UserPrincipal(1,"test","CUSTOMER",null,"test");assertEquals(400,assertThrows(ApiException.class,()->s.save(c,"USER",1,true)).status);assertEquals(403,assertThrows(ApiException.class,()->s.list(new UserPrincipal(2,"test","DRIVER",null,"test"),"FOOD",Map.of())).status);verifyNoInteractions(db);}
 @Test void favoriteListAlwaysScopedAndPrivate(){var db=mock(JpaSql.class);when(db.rows(anyString(),any(Object[].class))).thenReturn(List.of());var s=new FavoriteService(db,new CatalogService(db));s.list(new UserPrincipal(9,"test","CUSTOMER",null,"test"),"RESTAURANT",Map.of());var i=mockingDetails(db).getInvocations().iterator().next();assertTrue(i.getArgument(0,String.class).contains("fav.customer_id=?"));assertEquals(9L,((Number)i.getArgument(1)).longValue());}
 @Test void missingFavoriteTypeIs400Not500()throws Exception {org.springframework.test.web.servlet.setup.MockMvcBuilders.standaloneSetup(new FavoriteController(mock(FavoriteService.class))).setCustomArgumentResolvers(new org.springframework.security.web.method.annotation.AuthenticationPrincipalArgumentResolver()).setControllerAdvice(new ApiErrors()).build().perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/favorites")).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isBadRequest());}
}
